import{d as g,C as e,o as h,c as d,j as i,a,E as o,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"中庸·第3章","description":"《中庸》第 3 章——「中庸其至矣乎！民鲜能久矣。」叹中庸之德为至，而人鲜能长久行之。","frontmatter":{"title":"中庸·第3章","description":"《中庸》第 3 章——「中庸其至矣乎！民鲜能久矣。」叹中庸之德为至，而人鲜能长久行之。","category":"guide","aliases":["第3章","中庸第3章","民鲜能久矣"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-03.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-03.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-03.md"},b=g({...m,setup(p){const t=[{id:"tan",label:"中庸其至矣乎",showLabel:!0,sentences:[["子曰：“中庸其",{text:"至",glossary:"zhi"},"矣乎！",{text:"民",glossary:"min"},{text:"鲜",glossary:"xian"},"能久矣。”"]],note:"孔子叹：中庸大概是「至矣」（极至、无以复加）了吧！然而紧接一句「民鲜能久矣」——百姓很少能长久地做到它。此章正面推重中庸之德，同时点出「难久」之忧，为下文「道之不行」伏笔。"}],r=[{id:"zi",term:"子",pinyin:"zǐ",meaning:"此处指孔子。「子曰」即孔子说。《中庸》多引孔子之言立论。"},{id:"zhi",term:"至",pinyin:"zhì",meaning:"极、极至。「其至矣乎」谓中庸之为德，是德的极至。朱注：「过则失中，不及则未至，故惟中庸之德为至。」"},{id:"min",term:"民",pinyin:"mín",meaning:"人、众人。"},{id:"xian",term:"鲜",pinyin:"xiǎn",meaning:"少。此处读 xiǎn（少），非「新鲜」之 xiān。"},{id:"nengjiu",term:"能久",pinyin:"néng jiǔ",meaning:"能长久地行持。朱注：「人所同得，初无难事，但世教衰，民不兴行，故鲜能之，今已久矣」——「鲜能」与「久」并见。"}];return(c,n)=>{const l=e("DaoTextReading"),s=e("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第3章",tabindex:"-1"},[a("中庸·第3章 "),i("a",{class:"header-anchor",href:"#中庸·第3章","aria-label":'Permalink to "中庸·第3章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[a("本章只有一句，却一反一正：高处说中庸为"),i("strong",null,"至德"),a("，低处说"),i("strong",null,"民鲜能久"),a("。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),o(l,{colophon:"中庸其至矣乎 · 民鲜能久矣",tone:"ink",sections:t,glossary:r,"default-mode":"slips","aria-label":"中庸·第3章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),o(s,{items:[{term:"子",pinyin:["zǐ"],meaning:"此处指孔子。「子曰」即孔子说。《中庸》多引孔子之言立论。"},{term:"至",pinyin:["zhì"],meaning:"极、极至。「其至矣乎」谓中庸之为德，是德的极至。朱注：「过则失中，不及则未至，故惟中庸之德为至。」"},{term:"民",pinyin:["mín"],meaning:"人、众人。"},{term:"鲜",pinyin:["xiǎn"],meaning:"少。此处读 xiǎn（少），非「新鲜」之 xiān。"},{term:"能久",pinyin:["néng","jiǔ"],meaning:"能长久地行持。朱注：「人所同得，初无难事，但世教衰，民不兴行，故鲜能之，今已久矣」——「鲜能」与「久」并见。"}]}),n[4]||(n[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p>孔子说：「中庸大概是最高的德了吧！可是人们已经很少能长久地实行它了。」</p><p>——「鲜能久」有两层：既少有人能行，而且这种情况已经很久了。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第三章只有两句：一句<strong>感叹</strong>（「中庸其至矣乎」），一句<strong>实况</strong>（「民鲜能久矣」）。</p><p>承第二章「君子中庸，小人反中庸」而来，这一章把话说得更重：中庸是<strong>至德</strong>，可现实是——连能长久行它的人都少了。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它把中庸抬到「至德」，同时说它是常事</strong>：「其至矣乎」是说它高；但朱注紧接着说「人所同得，初无难事」——本是人人都能做到的事。<strong>最高的德，却落在最平常的事上</strong>，这是这一章最反常识的地方。</li><li><strong>它指出真正的难处不在「能」，而在「久」</strong>：不是做不到一次，是维持不住。所以它的敌人不是「太难」，是「不长久」。</li><li><strong>它给了一个现实解释</strong>：朱注说「世教衰，民不兴行，故鲜能之，今已久矣」——<strong>风气与教化</strong>衰了，能坚持的人自然少。难处不全在个人意志，也在所处环境。</li><li><strong>与第二章正好接上</strong>：第二章讲「君子而<strong>时中</strong>」（当下处得其当），本章讲「民鲜能<strong>久</strong>」（长久做得下去）——一时之中与长久之中，是两关。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>分清是「不能」还是「不久」</strong>：多数人不是不懂道理，而是做不到「一直」；先诊断，再用力。</li><li><strong>别把它供起来</strong>：朱子说「初无难事」——中庸不是高不可攀的境界，而是日日常常的分寸。</li><li><strong>留意环境</strong>：「世教衰，民不兴行」——身边的学风、风气会影响能不能守得住；择友择境，是「能久」的一部分。</li><li><strong>一次做到不算数</strong>：本章的判准是「久」，不是「曾经」。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>孔子说：中庸大概是最高的德了吧！可是人们已经很少能长久地做到它了。</p><p>这句话是<strong>一反一正</strong>：一面把它抬到最高（「至」），一面说出实况（「鲜能久」）。真正的难处，不在懂不懂——朱熹说中庸是「人所同得，初无难事」——而在<strong>能不能一直做下去</strong>：教化衰了、风气坏了，肯坚持的人就少了。</p><p>所以这一章真正的分量在最后两个字：<strong>「久矣」</strong>。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「其至矣乎」——为什么把它称作「至德」，而不是「基本要求」？这两者对人的要求有什么不同？</li><li>「鲜能久矣」——我的困难通常在「能」（做得到一次）还是「久」（一直做得下去）？</li><li>朱注说「初无难事」——若本不难，那我做不到的原因，是不知、是环境，还是不肯？</li><li>这一章只有两句话，把「高」与「难」都说了；如果只记一句，我记哪一句？为什么？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-02">中庸·第2章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-04">中庸·第4章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',22))])}}});export{f as __pageData,b as default};
